"use server";

import { revalidatePath } from "next/cache";

import { adminContext, NOT_ADMIN } from "@/lib/admin-context";
import { revalidateAgency } from "@/lib/revalidate";
import type { FormResult } from "@/lib/validation/lead";
import { overallOf, reviewSchema } from "@/lib/validation/review";

// Admin → Reviews: create or edit a review with the Clutch-style fields (service role, after
// the admin check). overall and verified_client are generated by the database.

const SAVE_FAILED = "We couldn't save that. Please try again.";

export async function saveReview(
  id: string | null,
  raw: unknown,
): Promise<FormResult<{ id: string }>> {
  const ctx = await adminContext();
  if (!ctx) return { ok: false, error: NOT_ADMIN };
  if (id !== null && !/^[0-9a-f-]{36}$/i.test(id)) return { ok: false, error: "Unknown review." };
  const parsed = reviewSchema.safeParse(raw);
  if (!parsed.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of parsed.error.issues) fieldErrors[issue.path.join(".")] ??= issue.message;
    return { ok: false, error: "Check the highlighted fields.", fieldErrors };
  }
  const v = parsed.data;
  const { db, log } = ctx;

  const [agency, service, industry, lead] = await Promise.all([
    db.from("agencies").select("slug").eq("id", v.agencyId).maybeSingle(),
    v.service ? db.from("services").select("id").eq("slug", v.service).maybeSingle() : null,
    v.reviewerIndustry
      ? db.from("industries").select("id").eq("slug", v.reviewerIndustry).maybeSingle()
      : null,
    v.leadId ? db.from("leads").select("id").eq("id", v.leadId).maybeSingle() : null,
  ]);
  if (!agency.data) return { ok: false, error: "That agency no longer exists." };
  if (v.leadId && !lead?.data)
    return {
      ok: false,
      error: "Check the highlighted fields.",
      fieldErrors: { leadId: "No lead with that ID." },
    };

  const overall = overallOf(v);
  const row = {
    agency_id: v.agencyId,
    status: v.status,
    author_name: v.authorName,
    author_company: v.authorCompany || null,
    reviewer_title: v.reviewerTitle || null,
    reviewer_industry_id: industry?.data?.id ?? null,
    reviewer_company_size: v.reviewerCompanySize || null,
    reviewer_country: v.reviewerCountry || null,
    service_id: service?.data?.id ?? null,
    budget_range: v.budgetRange || null,
    project_start: v.projectStart || null,
    project_end: v.projectEnd || null,
    score_quality: v.scoreQuality ? Number(v.scoreQuality) : null,
    score_schedule: v.scoreSchedule ? Number(v.scoreSchedule) : null,
    score_cost: v.scoreCost ? Number(v.scoreCost) : null,
    score_refer: v.scoreRefer ? Number(v.scoreRefer) : null,
    // The 1–5 star rating the directory shows: the rounded overall when there are scores.
    rating: overall !== null ? Math.round(overall) : Number(v.rating),
    body: v.body,
    lead_id: v.leadId || null,
  };

  const { data, error } = id
    ? await db.from("reviews").update(row).eq("id", id).select("id").maybeSingle()
    : await db.from("reviews").insert(row).select("id").single();
  if (error || !data) return { ok: false, error: SAVE_FAILED };

  await log(id ? "review.update" : "review.create", "agency", v.agencyId, {
    review: data.id,
    status: v.status,
  });
  revalidateAgency(agency.data.slug);
  revalidatePath("/admin/reviews");
  return { ok: true, data: { id: data.id } };
}
